def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 481 Anatomy and Physiology ----
H('481.d.1.A',3,"A student dissecting a preserved heart wonders why the left wall is thicker than the right. Forming this kind of puzzle from an observation is:","asking a scientific question",["filing a report","buying supplies","ending the lab"],"Observation leads to questions.")
H('481.d.1.A',4,"Before testing how exercise affects pulse, an anatomy class states exactly what is being studied and what will be measured. This step is:","defining the problem",["grading the lab","choosing lunch","cleaning glassware"],"A defined problem guides the plan.")
H('481.d.1.B',3,"To test how posture affects heart rate, a class changes only posture and keeps age, activity, and timing the same. This design is a:","controlled investigation",["random survey","guess","drawing"],"Only one variable changes.")
H('481.d.1.B',4,"Measuring pulse before and after jumping jacks on the same students is a comparative design because it compares:","two conditions",["two classrooms only","two teachers","two textbooks"],"Before and after conditions are compared.")
H('481.d.1.C',3,"During a dissection lab, students should wear gloves, goggles, and:","a lab apron",["sandals","a scarf","earbuds"],"PPE protects skin and clothes.")
H('481.d.1.C',4,"After a dissection, the safest way to handle used scalpels is to place them in a:","designated sharps container",["trash can","desk drawer","backpack"],"Sharps need special disposal.")
H('481.d.1.D',3,"A blood pressure cuff and a stethoscope are tools used in an anatomy lab to measure:","vital signs",["bone color","muscle names","tissue stains"],"They measure cardiovascular function.")
H('481.d.1.D',4,"Using a goniometer to measure the angle of a joint is an example of choosing a tool for an anatomy lab:","measurement",["recipe","budget","bus schedule"],"Tools match measurements.")
H('481.d.1.E',3,"In SI units, a student's height is best recorded in:","centimeters",["inches","feet","yards"],"SI length units are metric.")
H('481.d.1.E',4,"A resting pulse is recorded as 72 beats in 60 seconds. In SI-friendly units, this is 72 beats per:","minute",["hour","day","week"],"Time unit is minutes.")
H('481.d.1.F',3,"Students record resting heart rates in a table so the data can be compared. This is organizing:","quantitative data",["opinions only","rumors","stories only"],"Numbers are quantitative.")
H('481.d.1.F',4,"A lab report with a labeled bar graph of pulse before and after exercise is an example of organizing data with a:","visual display",["rumor","secret","menu"],"Graphs display data.")
H('481.d.1.G',3,"A plastic torso with removable organs helps students study the body by serving as a:","model",["receipt","recipe","badge"],"Models represent anatomy.")
H('481.d.1.G',4,"A flowchart showing how a nerve signal travels to a muscle is a model of a:","process",["building","country","holiday"],"Models represent processes.")
H('481.d.1.H',3,"The idea that all living things are made of cells is supported by countless observations. In science, such a well-supported explanation is called a:","theory",["guess","opinion","hunch"],"Theories are well supported.")
H('481.d.1.H',4,"A testable prediction such as exercise will raise the pulse is a:","hypothesis",["law","theory","fact"],"Hypotheses are testable predictions.")
H('481.d.2.A',3,"A plastic model of the skeleton is helpful but cannot show how bones:","grow and heal",["look","are named","are shaped"],"Models have limits.")
H('481.d.2.A',4,"A model of the lungs made with a bottle and balloons shows how air moves but not the actual:","gas exchange in alveoli",["size of the bottle","color of balloons","shape of a room"],"Models simplify.")
H('481.d.2.B',3,"A student sees that resting pulse is lower in students who exercise more often. She has identified a:","pattern",["mistake","label","tool"],"Patterns appear in data.")
H('481.d.2.B',4,"A scientist averages the pulse rates of 30 students to describe the class. The average is a statistical:","feature of the data",["error","hypothesis","law"],"Mean is a statistic.")
H('481.d.2.C',3,"Cardiac output equals heart rate times stroke volume. A heart that beats 70 times a minute with 70 mL per beat pumps:","4,900 mL per minute",["140 mL per minute","490 mL per minute","49 mL per minute"],"70 x 70 = 4,900.")
H('481.d.2.C',4,"If a student breathes 12 times a minute and moves 500 mL of air each breath, minute ventilation is:","6,000 mL",["512 mL","600 mL","60,000 mL"],"12 x 500 = 6,000.")
H('481.d.2.D',3,"Judging whether a wearable heart monitor is accurate and meets its goals is evaluating the:","design",["color","price tag only","name"],"Evaluate designs against goals.")
H('481.d.2.D',4,"Engineers testing an artificial joint check strength, safety, and fit. They are evaluating an engineering:","design",["opinion","logo","rumor"],"Designs are evaluated.")
H('481.d.3.A',3,"A student claims that fluid intake raises urine output and supports the claim with measured data. This is an explanation backed by:","evidence",["opinion","luck","gossip"],"Claims need evidence.")
H('481.d.3.A',4,"A proposed solution for preventing bone loss is stronger when it is supported by data and a:","model",["rumor","slogan","coin"],"Models and data support solutions.")
H('481.d.3.B',3,"Students present their findings on muscle fatigue to the class using a poster and clear:","explanations",["silence","riddles","jokes only"],"Communicate findings clearly.")
H('481.d.3.B',4,"In a lab team, one student records data, one measures, and one reports. Sharing roles is an example of:","collaboration",["competition","conflict","avoidance"],"Teams share work.")
H('481.d.3.C',3,"When classmates disagree about a result, a respectful scientist uses:","evidence",["insults","volume","rank"],"Evidence settles disputes.")
H('481.d.3.C',4,"A student disagrees with a lab partner's conclusion. The best response is to:","show the data supporting another view",["ignore the partner","delete the data","argue louder"],"Evidence-based argument.")
H('481.d.4.A',3,"To critique an article claiming a miracle bone supplement, a student checks the study's:","evidence and sample size",["font","cover","title length"],"Critique evidence.")
H('481.d.4.A',4,"A claim that stretching cures all muscle disease is based on one person's story. The critique is that it lacks:","sufficient evidence",["a title","a headline","an author"],"One anecdote is weak.")
H('481.d.4.B',3,"The discovery of X-rays by Wilhelm Roentgen changed medicine by letting doctors see:","bones inside the body",["the weather","a planet","a map"],"X-rays reveal bones.")
H('481.d.4.B',4,"William Harvey's work on circulation changed scientific thought by showing that blood:","circulates through the body",["is made in the liver and used up","is a fixed liquid","only moves in veins"],"Harvey described circulation.")
H('481.d.4.C',3,"A student exploring careers in anatomy could visit a university anatomy lab or a:","medical museum",["theme park","shopping mall","casino"],"Museums and labs provide information.")
H('481.d.4.C',4,"Professional organizations in health science are helpful to students because they describe training and:","career pathways",["fashion","vacations","cartoons"],"Organizations explain careers.")
H('481.d.5.A',3,"The six levels of structural organization begin with chemicals and build up through cells, tissues, organs, and organ systems to the:","organism",["atom","planet","species"],"Levels build to the whole organism.")
H('481.d.5.A',4,"Several tissues working together to perform a specific job form a(n):","organ",["cell","chemical","organism"],"Tissues form organs.")
H('481.d.5.B',3,"The term proximal means closer to the point of attachment. The elbow is proximal to the:","wrist",["shoulder","neck","chest"],"Proximal is nearer the trunk.")
H('481.d.5.B',4,"The directional term that means toward the midline of the body is:","medial",["lateral","distal","superficial"],"Medial is toward the midline.")
H('481.d.5.C',3,"All living organisms respond to stimuli, grow, reproduce, and carry out:","metabolism",["hibernation","evaporation","erosion"],"Metabolism is a life process.")
H('481.d.5.C',4,"A characteristic of living things is the ability to maintain a stable internal environment, called:","homeostasis",["inflation","fatigue","erosion"],"Homeostasis maintains balance.")
H('481.d.5.D',3,"A feedback loop that reverses a change and returns the body toward its set point is a:","negative feedback loop",["positive feedback loop","blind loop","broken loop"],"Negative feedback restores balance.")
H('481.d.5.D',4,"Blood clotting speeds itself up until the bleeding stops, which is an example of:","positive feedback",["negative feedback","no feedback","random feedback"],"Positive feedback amplifies change.")
H('481.d.5.E',3,"When the body cannot control blood sugar, as in diabetes, the failure to maintain homeostasis can cause:","disease",["balance","health","strength"],"Failure of homeostasis causes disease.")
H('481.d.5.E',4,"A body that cannot cool itself in extreme heat can develop dangerous overheating, called:","heat stroke",["hypothermia","frostbite","anemia"],"Overheating is a homeostatic failure.")
H('481.d.6.A',3,"A group of similar cells working together to do a job is called a:","tissue",["organ","system","molecule"],"Tissue is a group of similar cells.")
H('481.d.6.A',4,"The four primary tissue types are epithelial, connective, muscle, and:","nervous",["adipose","skeletal","vascular"],"Nervous is the fourth type.")
H('481.d.6.B',3,"Epithelial cells are packed tightly with little space between them, while connective tissue cells are usually spread out in a large amount of:","extracellular matrix",["empty air","muscle","skin"],"Matrix separates connective cells.")
H('481.d.6.B',4,"Tissue that covers surfaces and lines body cavities has tightly packed cells and is called:","epithelial tissue",["connective tissue","muscle tissue","nervous tissue"],"Epithelium covers and lines.")
H('481.d.6.C',3,"When skin is cut, cells divide to fill the gap and a clot forms. This process of normal healing is called tissue:","repair",["decay","loss","stress"],"Tissue repair restores structure.")
H('481.d.6.C',4,"In normal healing, the first stage after a cut is bleeding followed by the formation of a:","blood clot",["scar only","bone","tendon"],"Clotting stops bleeding.")
H('481.d.6.D',3,"The breakdown of glucose to release energy for cells is part of the metabolism of:","carbohydrates",["minerals","vitamins","water"],"Glucose is a carbohydrate.")
H('481.d.6.D',4,"Fats are broken down into glycerol and fatty acids, which are the building blocks of:","lipids",["proteins","sugars","nucleic acids"],"Lipids contain fatty acids.")
H('481.d.7.A',3,"The skull, vertebral column, and rib cage belong to the:","axial skeleton",["appendicular skeleton","muscular system","skin"],"Axial forms the central axis.")
H('481.d.7.A',4,"The bones of the arms, legs, shoulders, and hips make up the:","appendicular skeleton",["axial skeleton","cranium","spine"],"Appendicular includes limbs and girdles.")
H('481.d.7.B',3,"The elbow and knee are examples of joints that move like a door, called:","hinge joints",["pivot joints","gliding joints","saddle joints"],"Hinge joints bend in one plane.")
H('481.d.7.B',4,"The joint at the top of the neck that allows you to shake your head no is a:","pivot joint",["hinge joint","ball and socket joint","gliding joint"],"Pivot rotates.")
H('481.d.7.C',3,"The dense, hard outer layer of a bone is called:","compact bone",["spongy bone","marrow","cartilage"],"Compact bone is dense.")
H('481.d.7.C',4,"The inner, lighter layer of bone with many small spaces that hold red marrow is:","spongy bone",["compact bone","periosteum","enamel"],"Spongy bone is porous.")
H('481.d.7.D',3,"Besides supporting the body, the skeletal system protects organs such as the brain, which is inside the:","skull",["pelvis","femur","sternum"],"The skull protects the brain.")
H('481.d.7.D',4,"Red blood cells are produced in the red marrow of bones, which is the blood-forming function of the skeleton called:","hematopoiesis",["osteoporosis","ossification","digestion"],"Hematopoiesis is blood cell production.")
H('481.d.7.E',3,"The cells that build new bone matrix are:","osteoblasts",["osteoclasts","osteocytes","neurons"],"Blasts build.")
H('481.d.7.E',4,"The large cells that break down bone tissue so that calcium can be released are:","osteoclasts",["osteoblasts","osteocytes","fibroblasts"],"Clasts break down.")
H('481.d.7.F',3,"A fracture in which the broken bone pierces through the skin is a:","compound fracture",["simple fracture","greenstick fracture","hairline fracture"],"Open fracture breaks the skin.")
H('481.d.7.F',4,"A common fracture in children where the bone bends and cracks on one side without breaking completely is a:","greenstick fracture",["compound fracture","comminuted fracture","spiral fracture"],"Soft bones bend.")
H('481.d.7.G',3,"A disease that makes bones weak and brittle because of a loss of bone density is:","osteoporosis",["arthritis","scoliosis","gout"],"Osteoporosis thins bone.")
H('481.d.7.G',4,"An abnormal sideways curve of the spine is called:","scoliosis",["kyphosis","lordosis","osteoporosis"],"Scoliosis is a lateral curve.")
H('481.d.8.A',3,"The outermost layer of the skin is the:","epidermis",["dermis","hypodermis","muscle"],"Epidermis is the surface layer.")
H('481.d.8.A',4,"The thick layer of skin below the outermost layer, containing blood vessels, nerves, and hair follicles, is the:","dermis",["epidermis","cuticle","fascia"],"Dermis is the deeper layer.")
H('481.d.8.B',3,"The pigment made by melanocytes that gives skin much of its color is:","melanin",["keratin","collagen","hemoglobin"],"Melanin colors skin.")
H('481.d.8.B',4,"Besides melanin, skin color can be affected by blood flow, carotene, and exposure to:","sunlight",["moonlight","music","cold water only"],"Sun exposure changes pigment.")
H('481.d.8.C',3,"When a deep wound heals, collagen fibers form a patch of fibrous connective tissue called a:","scar",["blister","callus","freckle"],"Scar tissue is fibrous.")
H('481.d.8.C',4,"Deep wounds heal with scar tissue because the dermis cannot be fully replaced with its original:","structure",["color","name","pigment only"],"Scar differs from original tissue.")
H('481.d.8.D',3,"A bacterial skin infection of hair follicles forming a red, painful bump is a:","boil",["wart","mole","freckle"],"Boils are infected follicles.")
H('481.d.8.D',4,"The most serious type of skin cancer, which arises from melanocytes, is:","melanoma",["acne","eczema","psoriasis"],"Melanoma is deadly.")
H('481.d.9.A',3,"The muscular system moves the body, maintains posture, and produces:","heat",["bone","blood","enamel"],"Muscle contraction generates heat.")
H('481.d.9.A',4,"Shivering when you are cold helps the body maintain its temperature because muscles contracting produce:","heat",["cold","bone","sweat"],"Contractions produce heat.")
H('481.d.9.B',3,"Muscles move bones by pulling on them through strong cords called:","tendons",["ligaments","nerves","veins"],"Tendons attach muscle to bone.")
H('481.d.9.B',4,"To bend the arm at the elbow, the biceps contracts while the triceps relaxes. Muscles that work in opposite pairs are called:","antagonists",["agonists only","synergists","fixators"],"Antagonists oppose each other.")
H('481.d.9.C',3,"Muscle tissue can respond to a nerve signal, which is the characteristic of:","excitability",["elasticity only","hardness","coolness"],"Excitability is responsiveness.")
H('481.d.9.C',4,"The ability of muscle to shorten forcefully is called:","contractility",["extensibility","elasticity","excitability"],"Contractility is shortening.")
H('481.d.9.D',3,"Muscle found in the walls of the heart, which is striated and involuntary, is called:","cardiac muscle",["smooth muscle","skeletal muscle","voluntary muscle"],"Cardiac muscle is in the heart.")
H('481.d.9.D',4,"Muscle in the walls of the intestines that moves food along without conscious control is:","smooth muscle",["skeletal muscle","cardiac muscle","striated muscle"],"Smooth muscle is involuntary.")
H('481.d.9.E',3,"The smallest contractile unit of a muscle fiber is the:","sarcomere",["neuron","tendon","osteon"],"Sarcomeres contract.")
H('481.d.9.E',4,"The two main protein filaments in a sarcomere are actin and:","myosin",["keratin","collagen","insulin"],"Actin and myosin slide.")
H('481.d.9.F',3,"At the neuromuscular junction, a nerve releases the neurotransmitter:","acetylcholine",["insulin","dopamine only","adrenaline only"],"ACh triggers contraction.")
H('481.d.9.F',4,"For a muscle to contract, calcium is released inside the fiber, allowing myosin to bind to:","actin",["bone","skin","blood"],"Cross bridges form.")
H('481.d.9.G',3,"The large muscle on the front of the upper arm that bends the elbow is the:","biceps brachii",["triceps brachii","deltoid","gluteus maximus"],"Biceps flex the elbow.")
H('481.d.9.G',4,"The muscle that covers the shoulder and raises the arm to the side is the:","deltoid",["trapezius","pectoralis","gastrocnemius"],"The deltoid abducts the arm.")
H('481.d.9.H',3,"A genetic disease that causes progressive muscle weakness is muscular:","dystrophy",["atrophy","tension","fatigue"],"Muscular dystrophy weakens muscles.")
H('481.d.9.H',4,"A sudden, involuntary muscle contraction that causes pain is called a:","cramp",["tendon","fiber","reflex arc"],"Cramps are spasms.")
H('481.d.9.I',3,"A force that twists an object around an axis, such as the pull of a muscle on a lever bone, is called:","torque",["tension","pressure","friction"],"Torque is rotational force.")
H('481.d.9.I',4,"The bones act as levers, the joints as fulcrums, and the muscles provide the:","effort force",["load","resistance","base"],"Muscles supply force.")
H('481.d.10.A',3,"The nervous system's job of gathering information from inside and outside the body is its:","sensory function",["motor function","digestive function","storage function"],"Sensory input detects stimuli.")
H('481.d.10.A',4,"Sending commands from the brain to muscles and glands is the nervous system's:","motor function",["sensory function","integrative function","structural function"],"Motor output causes responses.")
H('481.d.10.B',3,"The five traditional senses are sight, hearing, taste, smell, and:","touch",["balance","pain","thirst"],"Touch is the fifth sense.")
H('481.d.10.B',4,"Sensory receptors convert stimuli into nerve impulses that travel to the:","brain",["stomach","bones","skin"],"Impulses reach the CNS.")
H('481.d.10.C',3,"Twelve pairs of nerves attached to the brain are the:","cranial nerves",["spinal nerves","sciatic nerves","autonomic nerves"],"Cranial nerves arise from the brain.")
H('481.d.10.C',4,"Thirty-one pairs of nerves branch off the spinal cord and carry signals to the trunk and limbs. These are the:","spinal nerves",["cranial nerves","optic nerves","vagus nerves"],"Spinal nerves exit the cord.")
H('481.d.10.D',3,"The colored part of the eye that controls how much light enters is the:","iris",["cornea","retina","lens"],"The iris adjusts the pupil.")
H('481.d.10.D',4,"The snail-shaped organ of the inner ear that converts sound vibrations into nerve signals is the:","cochlea",["retina","cornea","tympanum"],"The cochlea transduces sound.")
H('481.d.10.E',3,"The division of the peripheral nervous system that controls voluntary movement of skeletal muscle is the:","somatic nervous system",["autonomic nervous system","central nervous system","enteric system"],"Somatic is voluntary.")
H('481.d.10.E',4,"The division that regulates involuntary functions such as heart rate and digestion is the:","autonomic nervous system",["somatic nervous system","central nervous system","skeletal system"],"Autonomic is involuntary.")
H('481.d.10.F',3,"Cells that support and protect neurons rather than carrying impulses are called:","glial cells",["osteocytes","platelets","myocytes"],"Glia support neurons.")
H('481.d.10.F',4,"In the peripheral nervous system, the glial cells that wrap axons in a myelin sheath are:","Schwann cells",["astrocytes","microglia","ependymal cells"],"Schwann cells myelinate PNS axons.")
H('481.d.10.G',3,"In the brain, the tissue that appears pale because it contains many myelinated axons is:","white matter",["gray matter","blood","bone"],"Myelin gives a white appearance.")
H('481.d.10.G',4,"Neuron cell bodies and unmyelinated fibers make up the darker tissue called:","gray matter",["white matter","cartilage","marrow"],"Cell bodies form gray matter.")
H('481.d.10.H',3,"A neuron that carries impulses from sensory receptors toward the central nervous system is a:","sensory neuron",["motor neuron","interneuron","glial cell"],"Sensory neurons are afferent.")
H('481.d.10.H',4,"The electrical signal that travels along an axon when a neuron is stimulated enough is called an:","action potential",["reflex arc","synapse","hormone"],"Action potentials carry the signal.")
H('481.d.10.I',3,"A chemical that carries a signal across a synapse from one neuron to the next is a:","neurotransmitter",["hormone","enzyme","antibody"],"Neurotransmitters cross the gap.")
H('481.d.10.I',4,"The neurotransmitter that stimulates skeletal muscle contraction is:","acetylcholine",["serotonin","insulin","melatonin"],"ACh acts at neuromuscular junctions.")
H('481.d.10.J',3,"A disease in which the myelin sheath of nerves is damaged, causing weakness and vision problems, is multiple:","sclerosis",["dystrophy","fibrosis","stenosis"],"MS is a demyelinating disease.")
H('481.d.10.J',4,"A sudden interruption of blood flow to part of the brain that can cause paralysis or speech loss is a:","stroke",["sprain","cramp","seizure only"],"A stroke damages brain tissue.")
H('481.d.11.A',3,"The pituitary gland, thyroid, adrenal glands, and pancreas are all part of the:","endocrine system",["digestive system","skeletal system","respiratory system"],"Endocrine glands secrete hormones.")
H('481.d.11.A',4,"The small gland at the base of the brain often called the master gland is the:","pituitary gland",["thymus","pineal gland","thyroid"],"The pituitary regulates other glands.")
H('481.d.11.B',3,"Glands that release their products directly into the bloodstream are:","endocrine glands",["exocrine glands","sweat glands","salivary glands"],"Endocrine glands are ductless.")
H('481.d.11.B',4,"Sweat glands and salivary glands release secretions through ducts, so they are:","exocrine glands",["endocrine glands","ductless glands","pineal glands"],"Exocrine glands use ducts.")
H('481.d.11.C',3,"The hormone from the pancreas that lowers blood sugar is:","insulin",["thyroxine","cortisol","estrogen"],"Insulin lowers glucose.")
H('481.d.11.C',4,"The thyroid gland produces thyroxine, a hormone that controls the body's:","metabolic rate",["bone length","hair color","eye color"],"Thyroxine controls metabolism.")
H('481.d.11.D',3,"Insulin and glucagon work together to keep blood sugar in a narrow range, maintaining:","homeostasis",["disease","growth","fatigue"],"Hormones regulate homeostasis.")
H('481.d.11.D',4,"When blood calcium is low, parathyroid hormone raises it by pulling calcium from bone. This hormone helps keep the body's calcium:","balanced",["low","unstable","unmeasured"],"PTH restores calcium balance.")
H('481.d.11.E',3,"A gland that is turned on by a signal from the brain is regulated by a:","neural stimulus",["hormonal stimulus","humoral stimulus","bone stimulus"],"Neural stimuli come from nerves.")
H('481.d.11.E',4,"When rising blood glucose directly triggers the pancreas to release insulin, the gland is regulated by a:","humoral stimulus",["neural stimulus","hormonal stimulus","skeletal stimulus"],"Humoral = blood chemistry.")
H('481.d.11.F',3,"A disease in which the body does not make enough insulin or cannot use it properly is:","diabetes mellitus",["Graves disease","Addison disease","goiter"],"Diabetes involves insulin problems.")
H('481.d.11.F',4,"An overactive thyroid gland, which can cause weight loss and a rapid heartbeat, is called:","hyperthyroidism",["hypothyroidism","acromegaly","dwarfism"],"Hyper means excess.")
H('481.d.12.A',3,"The organs that filter blood and make urine are the:","kidneys",["ureters","bladder","urethra"],"Kidneys filter blood.")
H('481.d.12.A',4,"Tubes that carry urine from the kidneys to the bladder are the:","ureters",["urethra","nephrons","arteries"],"Ureters move urine to the bladder.")
H('481.d.12.B',3,"Urine leaves the body through a tube called the:","urethra",["ureter","aorta","trachea"],"Urethra is the exit.")
H('481.d.12.B',4,"The urethra in males is longer than in females and also carries:","semen",["blood","bile","lymph"],"The male urethra is shared.")
H('481.d.12.C',3,"The microscopic filtering unit of a kidney is the:","nephron",["neuron","alveolus","osteon"],"Nephrons filter blood.")
H('481.d.12.C',4,"In a nephron, blood is first filtered in a cluster of capillaries called the:","glomerulus",["alveolus","cochlea","villus"],"The glomerulus filters.")
H('481.d.12.D',3,"The kidneys maintain fluid balance by adjusting how much water is kept or lost in:","urine",["bone","skin only","hair"],"Urine output regulates fluid.")
H('481.d.12.D',4,"The hormone ADH signals the kidneys to reabsorb more water, which helps the body avoid:","dehydration",["hydration","growth","digestion"],"ADH conserves water.")
H('481.d.12.E',3,"Normal urine is mostly water and also contains urea and:","salts",["red blood cells","large proteins","glucose in large amounts"],"Urine has dissolved wastes.")
H('481.d.12.E',4,"The three main steps of urine formation are filtration, reabsorption, and:","secretion",["digestion","absorption only","synthesis"],"Secretion adds wastes.")
H('481.d.12.F',3,"When blood pressure falls, the kidneys release renin, showing that the renal system works with the nervous system and:","the endocrine system",["the skeletal system","the integumentary system","the digestive system only"],"Renin-angiotensin integrates systems.")
H('481.d.12.F',4,"The adrenal hormone aldosterone helps the kidneys keep sodium and water, linking the renal and endocrine systems to control:","blood pressure",["bone density","skin color","hair growth"],"Aldosterone raises BP.")
H('481.d.12.G',3,"An infection of the bladder is called:","cystitis",["nephritis","hepatitis","gastritis"],"Cystitis is bladder infection.")
H('481.d.12.G',4,"Hard deposits of minerals that form in the kidney and can block the flow of urine are kidney:","stones",["clots","cysts only","fibers"],"Kidney stones obstruct flow.")
H('481.d.13.A',3,"The main function of the cardiovascular system is to transport oxygen, nutrients, and wastes by pumping:","blood",["air","food","bile"],"The heart pumps blood.")
H('481.d.13.A',4,"Besides transport, the cardiovascular system helps regulate body temperature and protect the body through white blood cells and:","clotting",["digestion","hearing","vision"],"Platelets clot blood.")
H('481.d.13.B',3,"Vessels that carry blood away from the heart are:","arteries",["veins","capillaries","valves"],"Arteries carry blood away.")
H('481.d.13.B',4,"The tiny vessels where oxygen and nutrients are exchanged with tissues are:","capillaries",["arteries","veins","venules"],"Capillaries exchange materials.")
H('481.d.13.C',3,"Systemic circulation carries oxygen-rich blood from the left side of the heart to the body and returns oxygen-poor blood to the:","right atrium",["left atrium","left ventricle","lungs directly"],"Systemic blood returns to the right atrium.")
H('481.d.13.C',4,"The largest artery that carries blood from the left ventricle to the body is the:","aorta",["pulmonary artery","vena cava","carotid artery"],"The aorta leaves the left ventricle.")
H('481.d.13.D',3,"If blood vessels narrow while the heart output stays the same, blood pressure will:","rise",["fall","stop","disappear"],"Resistance raises pressure.")
H('481.d.13.D',4,"Blood flows from areas of high pressure to areas of low pressure, so blood moves fastest where the pressure difference is:","greatest",["smallest","zero","constant"],"Gradient drives flow.")
H('481.d.13.E',3,"The circulation that supplies the heart muscle itself with blood is the:","coronary circulation",["pulmonary circulation","systemic circulation","portal circulation"],"Coronary arteries feed the heart.")
H('481.d.13.E',4,"Blood is carried to the lungs to pick up oxygen by the:","pulmonary circulation",["coronary circulation","systemic circulation","cerebral circulation"],"The pulmonary loop goes to the lungs.")
H('481.d.13.F',3,"On an electrocardiogram, the large spike that shows the ventricles contracting is the:","QRS complex",["P wave","T wave","U wave"],"QRS shows ventricular depolarization.")
H('481.d.13.F',4,"The P wave on an EKG represents the electrical activation of the:","atria",["ventricles","aorta","valves"],"P wave = atrial depolarization.")
H('481.d.13.G',3,"The part of the nervous system that speeds up the heart during exercise is the:","sympathetic nervous system",["parasympathetic nervous system","somatic nervous system","enteric system"],"Sympathetic raises heart rate.")
H('481.d.13.G',4,"The vagus nerve slows the heart, so it belongs to the:","parasympathetic division",["sympathetic division","somatic division","skeletal division"],"Parasympathetic slows the heart.")
H('481.d.13.H',3,"A condition in which arteries become narrowed and hardened by plaque is:","atherosclerosis",["anemia","angina","arrhythmia"],"Plaque narrows arteries.")
H('481.d.13.H',4,"A heart condition in which the heartbeat is irregular is called:","arrhythmia",["anemia","atherosclerosis","hypertension"],"Arrhythmia is abnormal rhythm.")
H('481.d.14.A',3,"The lymphatic system helps the cardiovascular system by returning excess tissue fluid to the:","bloodstream",["stomach","skull","skin"],"Lymph drains back into blood.")
H('481.d.14.A',4,"Lymphatic vessels in the intestines absorb dietary fats, showing the lymphatic system also works with the:","digestive system",["skeletal system","urinary system","integumentary system"],"Lacteals absorb fat.")
H('481.d.14.B',3,"Small bean-shaped organs that filter lymph and house immune cells are lymph:","nodes",["vessels","valves","ducts"],"Lymph nodes filter lymph.")
H('481.d.14.B',4,"The lymphatic organ in the upper left abdomen that filters blood and stores platelets is the:","spleen",["thymus","tonsil","appendix"],"The spleen filters blood.")
H('481.d.14.C',3,"White blood cells that make antibodies are:","B lymphocytes",["red blood cells","platelets","neurons"],"B cells make antibodies.")
H('481.d.14.C',4,"White blood cells that engulf and digest bacteria by phagocytosis include:","macrophages",["platelets","erythrocytes","osteoclasts"],"Macrophages are phagocytes.")
H('481.d.14.D',3,"A person with type A blood has A antigens on their red blood cells and has antibodies against type:","B",["A","AB","O antigens only"],"Type A makes anti-B.")
H('481.d.14.D',4,"People with type O negative blood are called universal donors for red blood cells because their cells lack:","A, B, and Rh antigens",["all proteins","iron","hemoglobin"],"No A, B, or Rh antigens to react.")
H('481.d.14.E',3,"The skin and mucous membranes protect the body from germs as the first line of defense, which is part of nonspecific:","immunity",["growth","hunger","digestion"],"Barriers are nonspecific.")
H('481.d.14.E',4,"A fever helps defend against infection by making conditions less favorable for the:","pathogens",["bones","muscles","neurons"],"Fever hinders microbes.")
H('481.d.14.F',3,"A foreign substance that triggers the immune system to respond is a(n):","antigen",["antibody","enzyme","hormone"],"Antigens trigger immunity.")
H('481.d.14.F',4,"Y-shaped proteins made by B cells that bind to a specific antigen are:","antibodies",["antigens","hormones","platelets"],"Antibodies bind antigens.")
H('481.d.14.G',3,"A disease caused by a virus that attacks helper T cells and weakens the immune system is:","AIDS",["asthma","anemia","arthritis"],"HIV causes AIDS.")
H('481.d.14.G',4,"When the immune system mistakenly attacks the body's own tissues, the condition is called an:","autoimmune disease",["allergy","infection","tumor"],"Autoimmunity attacks self.")
H('481.d.15.A',3,"The long tube from the mouth to the anus through which food passes is the:","alimentary canal",["lymph duct","trachea","aorta"],"The alimentary canal is the GI tract.")
H('481.d.15.A',4,"The organ where most chemical digestion and absorption of nutrients occurs is the:","small intestine",["large intestine","esophagus","stomach"],"The small intestine absorbs nutrients.")
H('481.d.15.B',3,"Chewing and the churning of the stomach are examples of:","mechanical digestion",["chemical digestion","absorption","excretion"],"Mechanical physically breaks food.")
H('481.d.15.B',4,"Enzymes such as amylase in saliva breaking starch into sugars are an example of:","chemical digestion",["mechanical digestion","peristalsis","segmentation"],"Enzymes chemically digest.")
H('481.d.15.C',3,"Excess glucose is stored in the liver and muscles as:","glycogen",["cholesterol","insulin","bile"],"Glycogen stores glucose.")
H('481.d.15.C',4,"When the body has more energy than it needs, extra calories can be stored in adipose tissue as:","fat",["bone","skin","muscle protein"],"Fat is stored energy.")
H('481.d.15.D',3,"Stomach acid backing up into the esophagus and causing heartburn is called gastroesophageal reflux disease, or:","GERD",["IBS","COPD","ALS"],"GERD is acid reflux.")
H('481.d.15.D',4,"An inflammation of the liver, often caused by a virus, is:","hepatitis",["gastritis","colitis","nephritis"],"Hepat means liver.")
H('481.d.16.A',3,"Air entering through the nose travels through the pharynx, larynx, trachea, bronchi, and finally reaches the tiny air sacs called:","alveoli",["villi","nephrons","glomeruli"],"Alveoli are the exchange sites.")
H('481.d.16.A',4,"The structure that closes over the trachea during swallowing to keep food out of the airway is the:","epiglottis",["uvula","tonsil","larynx wall"],"The epiglottis covers the glottis.")
H('481.d.16.B',3,"The nose, pharynx, and larynx make up the upper respiratory tract, which warms, moistens, and filters the:","air",["food","blood","urine"],"Upper tract conditions air.")
H('481.d.16.B',4,"The trachea, bronchi, and lungs make up the lower respiratory tract, where the main job is:","gas exchange",["digestion","hearing","balance"],"Lower tract exchanges gases.")
H('481.d.16.C',3,"The movement of air into and out of the lungs is called pulmonary:","ventilation",["circulation","digestion","filtration"],"Ventilation is breathing.")
H('481.d.16.C',4,"The exchange of oxygen and carbon dioxide between the blood and body cells is called:","internal respiration",["external respiration","ventilation","expiration"],"Internal respiration happens at tissues.")
H('481.d.16.D',3,"Red blood cells carry oxygen from the lungs to the body, showing the respiratory system works closely with the:","cardiovascular system",["skeletal system","integumentary system","urinary system"],"Oxygen is transported by blood.")
H('481.d.16.D',4,"Oxygen binds to the protein in red blood cells called:","hemoglobin",["keratin","collagen","myosin"],"Hemoglobin carries oxygen.")
H('481.d.16.E',3,"During exercise, breathing rate increases because muscles need more oxygen and produce more carbon dioxide, which stimulates the:","respiratory center in the brain",["stomach","skin","kidneys"],"CO2 drives breathing rate.")
H('481.d.16.E',4,"At high altitude, the air has less oxygen, so a person may breathe faster to maintain adequate oxygen:","levels in the blood",["in the shoes","on the skin","in the stomach"],"Altitude affects respiration.")
H('481.d.16.F',3,"A chronic disease in which airways become inflamed and narrow, causing wheezing, is:","asthma",["emphysema","tuberculosis","pneumonia"],"Asthma narrows airways.")
H('481.d.16.F',4,"An infection of the lungs in which the alveoli fill with fluid is:","pneumonia",["asthma","bronchitis only","sinusitis"],"Pneumonia fills air sacs.")
H('481.d.17.A',3,"The early embryo develops three primary germ layers that go on to form all tissues and organs. The process is called embryological:","development",["decay","repair","starvation"],"Germ layers differentiate.")
H('481.d.17.A',4,"The germ layer that gives rise to the skin and nervous system is the:","ectoderm",["mesoderm","endoderm","myoderm"],"Ectoderm forms skin and nerves.")
H('481.d.17.B',3,"The female organs that produce egg cells are the:","ovaries",["testes","uterus","fallopian tubes"],"Ovaries produce ova.")
H('481.d.17.B',4,"The male organs that produce sperm and the hormone testosterone are the:","testes",["prostate","ovaries","seminal vesicles"],"Testes produce sperm.")
H('481.d.17.C',3,"The process of forming sperm cells is called:","spermatogenesis",["oogenesis","mitosis","fertilization"],"Spermatogenesis makes sperm.")
H('481.d.17.C',4,"The process of forming egg cells in the ovary is called:","oogenesis",["spermatogenesis","meiosis only","fission"],"Oogenesis makes eggs.")
H('481.d.17.D',3,"The hormone estrogen, produced mainly in the ovaries, influences the female:","reproductive cycle",["digestive cycle","sleep cycle","water cycle"],"Estrogen drives the cycle.")
H('481.d.17.D',4,"A surge of luteinizing hormone triggers the release of an egg from the ovary in a process called:","ovulation",["menstruation","implantation","fertilization"],"LH surge triggers ovulation.")
H('481.d.17.E',3,"During puberty in males, the hormone that causes a deeper voice and facial hair is:","testosterone",["estrogen","insulin","oxytocin"],"Testosterone drives male traits.")
H('481.d.17.E',4,"The pituitary hormones FSH and LH help control maturation of the reproductive organs and are called:","gonadotropins",["thyrotropins","mineralocorticoids","catecholamines"],"FSH and LH stimulate gonads.")
H('481.d.17.F',3,"A sexually transmitted infection caused by a bacterium that can be treated with antibiotics is:","chlamydia",["measles","influenza","mumps"],"Chlamydia is bacterial.")
H('481.d.17.F',4,"A condition in which uterine-like tissue grows outside the uterus, causing pain, is:","endometriosis",["osteoporosis","emphysema","gastritis"],"Endometriosis is a reproductive disorder.")
H('481.d.18.A',3,"Replacing a failed kidney with one from a donor is an advance in medicine at the organ level called an organ:","transplant",["cure","search","lift"],"Transplants replace organs.")
H('481.d.18.A',4,"A machine that takes over the work of the heart and lungs during surgery is a heart-lung:","bypass machine",["radio","scale","microscope"],"Bypass machines support circulation.")
H('481.d.18.B',3,"Treating disease by changing a person's genes at the cellular level is called gene:","therapy",["farming","mapping","cloning"],"Gene therapy alters cells.")
H('481.d.18.B',4,"Stem cells are valuable in medicine because they can develop into many types of:","specialized cells",["rocks","metals","fabrics"],"Stem cells differentiate.")
# ---- 482 Pathophysiology ----
H('482.d.1.A',3,"A student reads a case study in which several patients all develop rashes after eating at the same restaurant and asks what could cause it. This is forming a:","testable question",["diagnosis","prescription","treatment plan"],"Observations lead to questions.")
H('482.d.1.A',4,"In a pathology investigation, defining the problem includes stating what is unknown and which patient characteristics will be:","compared",["hidden","ignored","erased"],"Problems define variables.")
H('482.d.1.B',3,"An investigation that observes patients without changing anything, such as recording symptoms of a disease over time, is:","descriptive",["experimental","comparative","controlled"],"Descriptive studies record.")
H('482.d.1.B',4,"A study that compares smokers and nonsmokers for lung disease rates is a:","comparative investigation",["descriptive log","hypothesis","model"],"Groups are compared.")
H('482.d.1.C',3,"A lab worker handling a blood sample should wear gloves and treat the sample as potentially infectious by using:","standard precautions",["no precautions","bare hands","open containers"],"Standard precautions protect workers.")
H('482.d.1.C',4,"When a dropper of culture spills on the lab bench, the first step is to put on gloves and:","cover and disinfect the spill",["wipe it with a dry tissue","leave it","blow on it"],"Disinfect spills.")
H('482.d.1.D',3,"A spreadsheet program helps organize patient lab values so that a student can calculate:","averages",["diagnoses","prescriptions","insurance"],"Software supports calculations.")
H('482.d.1.D',4,"Data-collecting probes, calculators, and spreadsheets are examples of tools used to collect and analyze:","scientific data",["fashion","menus","comics"],"Tools gather data.")
H('482.d.1.E',3,"A patient's temperature in a research lab is recorded in degrees:","Celsius",["Fahrenheit","Kelvin only","Rankine"],"SI-friendly units use Celsius.")
H('482.d.1.E',4,"In SI units, the amount of glucose in blood may be recorded in millimoles per:","liter",["inch","ounce","day"],"SI concentration uses liters.")
H('482.d.1.F',3,"Recording patients' symptoms and test results in a lab notebook helps researchers later:","compare cases",["lose data","guess","erase facts"],"Notebooks support comparison.")
H('482.d.1.F',4,"Organizing data in tables and graphs makes it easier to see how a disease changes:","over time",["by color","by font","by weight of paper"],"Visual organization shows trends.")
H('482.d.1.G',3,"A diagram showing how a virus enters a cell and copies itself is a model of:","a disease process",["a recipe","a map","a budget"],"Models show processes.")
H('482.d.1.G',4,"Computer models of how an epidemic spreads through a town are used to predict the:","number of cases",["weather","price of houses","fashion trends"],"Models make predictions.")
H('482.d.1.H',3,"The idea that microorganisms cause many diseases is supported by a large body of evidence. In science, such a well-supported explanation is called a:","theory",["guess","law only","rumor"],"Germ theory is a theory.")
H('482.d.1.H',4,"A statement that a certain bacterium causes a disease, written before testing, is a:","hypothesis",["theory","law","conclusion"],"A hypothesis is testable.")
H('482.d.2.A',3,"Using mice to model human disease has the advantage of being cheap and quick but the limitation that mice are not exactly like:","people",["rats","insects","fish"],"Model limits.")
H('482.d.2.A',4,"A computer model of heart disease is limited by the data and assumptions that went into building its:","design",["font","logo","title"],"Models are simplified.")
H('482.d.2.B',3,"A scientist sees that cases of influenza rise in winter and fall in summer. She has identified a:","seasonal pattern",["calculation error","new species","fossil"],"Patterns in data.")
H('482.d.2.B',4,"A graph of the number of new cases each week for a year shows a sharp spike. A scientist would analyze this as a statistical:","feature of the data",["decoration","mistake","law"],"Spikes are features.")
H('482.d.2.C',3,"If 8 of 200 people in a town have a disease, the percentage with the disease is:","4 percent",["8 percent","25 percent","16 percent"],"8 / 200 = 0.04.")
H('482.d.2.C',4,"A virus population doubles every 3 hours. Starting with 50 particles, after 9 hours there will be:","400",["150","200","450"],"50 x 2 x 2 x 2 = 400.")
H('482.d.2.D',3,"Comparing a new test for infection against the older test to see if it is accurate is evaluating an experimental:","design",["opinion","slogan","logo"],"Designs are evaluated.")
H('482.d.2.D',4,"A hospital tests a new hand-washing station to see if infection rates drop. This is evaluating an engineering:","design",["menu","fashion","policy name"],"Engineering designs are evaluated with outcomes.")
H('482.d.3.A',3,"A student explains why a patient has swelling and supports the explanation with lab results and an inflammation model. The explanation is supported by:","data and models",["opinion","rumors","guesses"],"Evidence supports explanations.")
H('482.d.3.A',4,"A proposed solution for reducing hospital infections is stronger when data show that infection rates:","fell after the change",["stayed the same","rose","were not measured"],"Data show effectiveness.")
H('482.d.3.B',3,"Researchers share study results with other scientists by writing reports and giving presentations. This is:","communication",["secrecy","guessing","delay"],"Communicating results.")
H('482.d.3.B',4,"In a group project on disease prevention, students assign roles, share findings, and combine their ideas. This is:","collaboration",["competition","avoidance","conflict"],"Teamwork.")
H('482.d.3.C',3,"During a debate about a vaccine study, a respectful scientist responds to a challenge by:","citing evidence",["shouting","walking away","insulting"],"Argue with evidence.")
H('482.d.3.C',4,"When two researchers disagree on a study's conclusion, they can resolve the disagreement by:","reexamining the data",["hiding the study","ignoring each other","guessing"],"Review the evidence.")
H('482.d.4.A',3,"To evaluate a news article claiming a food cures cancer, a student checks the article's:","evidence",["headline only","font","length"],"Evidence is key.")
H('482.d.4.A',4,"A study about a drug has only five patients and no control group. A critic would conclude that the study's explanation is:","weak",["certain","proven","perfect"],"Small, uncontrolled studies are weak.")
H('482.d.4.B',3,"John Snow traced a cholera outbreak to a contaminated water pump, which changed thinking about how disease:","spreads",["heals","feels","looks"],"Snow's work founded epidemiology.")
H('482.d.4.B',4,"The discovery of penicillin changed the treatment of bacterial infections and led to the field of:","antibiotics",["astronomy","geology","aviation"],"Penicillin began the antibiotic era.")
H('482.d.4.C',3,"A student interested in pathology could learn about careers from a university department or a:","professional society",["gossip site","shopping website","game"],"Reliable career sources.")
H('482.d.4.C',4,"Libraries and medical museums help students research the history of:","disease and medicine",["cooking","sports","fashion"],"Resources aid research.")
H('482.d.5.A',3,"Abnormal changes at the cellular level, such as swelling or shrinking of cells, are the starting point of many:","diseases",["recipes","games","fashions"],"Cell injury underlies disease.")
H('482.d.5.A',4,"A cell that is injured and cannot recover will undergo cell death, which may be programmed, called apoptosis, or caused by injury, called:","necrosis",["mitosis","osmosis","meiosis"],"Necrosis is death from injury.")
H('482.d.5.B',3,"A change in the DNA sequence of a gene is a:","mutation",["translation","fusion","hormone"],"Mutations alter DNA.")
H('482.d.5.B',4,"An abnormal mass of tissue that forms when cells divide uncontrollably is a:","neoplasm",["nephron","neuron","nucleus"],"Neoplasms are new growths.")
H('482.d.5.C',3,"Factors that contribute to the risk of disease include age, gender, genetics, and:","lifestyle",["birthday cake","favorite color","shoe size"],"Lifestyle affects risk.")
H('482.d.5.C',4,"A person whose family has a history of heart disease has an increased risk because of a factor called:","heredity",["hobby","rumor","nationality only"],"Heredity influences disease.")
H('482.d.5.D',3,"When blood loss lowers blood pressure, the heart rate rises to maintain circulation. This is a compensating mechanism that tries to restore:","homeostasis",["illness","injury","infection"],"Compensation protects balance.")
H('482.d.5.D',4,"If the body cannot compensate, as in severe blood loss, the result may be a life-threatening condition called:","shock",["fatigue","itching","sneezing"],"Failure to compensate causes shock.")
H('482.d.6.A',3,"A Gram stain separates bacteria into two groups based on the structure of their:","cell walls",["flagella","nuclei","ribosomes"],"Gram stain reveals cell wall type.")
H('482.d.6.A',4,"Spherical bacteria are called cocci and rod-shaped bacteria are called:","bacilli",["spirilla","vibrios","amoebae"],"Bacilli are rods.")
H('482.d.6.B',3,"The stage of pathogenesis after exposure and before symptoms begin is the:","incubation period",["recovery period","convalescence","acute stage"],"Incubation precedes symptoms.")
H('482.d.6.B',4,"The stage of a disease when symptoms are at their worst is the:","acute stage",["incubation period","prodromal stage","convalescent stage"],"Acute stage peaks.")
H('482.d.6.C',3,"The skin, mucous membranes, and stomach acid are barriers that make up the body's natural:","defense systems",["food sources","weak points","hormones"],"Barriers defend against infection.")
H('482.d.6.C',4,"White blood cells that engulf pathogens are part of the body's natural defense against:","infection",["hunger","growth","sleep"],"Phagocytes fight infection.")
H('482.d.6.D',3,"A preparation that trains the immune system to recognize a pathogen so that the person does not get the disease is a:","vaccine",["antibiotic","analgesic","antacid"],"Vaccines prevent disease.")
H('482.d.6.D',4,"Drugs that kill or stop the growth of bacteria are:","antibiotics",["antivirals","vaccines","vitamins"],"Antibiotics treat bacterial infection.")
H('482.d.6.E',3,"Exposure to asbestos, smoke, and other pollution can cause disease by damaging the cells of the:","lungs",["bones only","hair","nails"],"Pollutants harm lungs.")
H('482.d.6.E',4,"Radiation, certain chemicals, and some viruses can cause cancer because they can damage the cell's:","DNA",["shell","skin","hair"],"Carcinogens damage DNA.")
H('482.d.7.A',3,"Doctors study the cause of a disease, its signs and symptoms, how it is diagnosed, and how it is likely to progress. The cause is called its:","etiology",["prognosis","pathology","anatomy"],"Etiology means cause.")
H('482.d.7.A',4,"The expected course and outcome of a disease is called its:","prognosis",["etiology","diagnosis","symptom"],"Prognosis predicts outcome.")
H('482.d.7.B',3,"An imaging technique that uses magnetic fields and radio waves to make detailed pictures of soft tissue is:","MRI",["EKG","X-ray","ultrasound"],"MRI images soft tissue.")
H('482.d.7.B',4,"Using a small camera on a flexible tube to look inside the digestive tract is called:","endoscopy",["dialysis","biopsy","transfusion"],"Endoscopy views internal organs.")
H('482.d.7.C',3,"Diseases such as malaria and tuberculosis have reemerged in some regions partly because of drug-resistant strains and:","travel and poverty",["better sanitation","fewer people","vaccines for all"],"Reemergence has several causes.")
H('482.d.7.C',4,"A disease that was once controlled and then returns is called a:","reemerging disease",["new disease","genetic disease","chronic disease"],"Reemerging means it returned.")
H('482.d.7.D',3,"An infection that a patient acquires during a stay in a hospital is called a:","nosocomial infection",["genetic infection","congenital infection","chronic infection"],"Nosocomial = hospital-acquired.")
H('482.d.7.D',4,"The most important and simple way to prevent the spread of infections in hospitals is proper:","hand washing",["air freshening","painting walls","wearing jewelry"],"Hand hygiene prevents spread.")
H('482.d.7.E',3,"Bacteria that no longer respond to common antibiotics, such as MRSA, are called antibiotic-:","resistant",["sensitive","dependent","friendly"],"MRSA resists methicillin.")
H('482.d.7.E',4,"Antibiotic resistance increases when people take antibiotics for viral infections or do not complete:","the prescribed course",["a lunch break","an exercise plan","a shopping trip"],"Misuse creates resistance.")
H('482.d.7.F',3,"A disease that is present at birth, such as cystic fibrosis, is called:","congenital",["acquired","iatrogenic","idiopathic"],"Congenital means from birth.")
H('482.d.7.F',4,"A disease with a sudden onset and a short duration, such as the flu, is:","acute",["chronic","congenital","degenerative"],"Acute is short and sudden.")
H('482.d.7.G',3,"Diseases such as lupus and multiple sclerosis involve the immune system attacking the body's own cells, so they are called:","autoimmune diseases",["infectious diseases","nutritional diseases","traumatic injuries"],"Autoimmunity is self-attack.")
H('482.d.7.G',4,"Diabetes and Parkinson's disease can be managed over years with treatment and lifestyle changes, which is characteristic of a:","chronic disease",["acute disease","wound","poisoning"],"Chronic diseases last long.")
H('482.d.8.A',3,"A practice that keeps an area free from germs is called:","asepsis",["sepsis","antisepsis only","contamination"],"Asepsis prevents infection.")
H('482.d.8.A',4,"Separating patients who have a contagious disease from other people to prevent spread is:","isolation",["rehabilitation","immunization","transfusion"],"Isolation limits spread.")
H('482.d.8.B',3,"Long-term stress can weaken the immune system and raise the risk of:","illness",["growth","strength","height"],"Chronic stress hurts health.")
H('482.d.8.B',4,"With aging, bones lose density and skin loses elasticity, which are changes in body:","structure and function",["names","colors","addresses"],"Aging changes the body.")
H('482.d.8.C',3,"A lab report shows a patient's white blood cell count is much higher than the normal range. This most likely indicates:","an infection",["a broken bone","hunger","normal health"],"High WBC suggests infection.")
H('482.d.8.C',4,"A fasting blood glucose reading well above the reference range is interpreted as a possible sign of:","diabetes",["anemia","asthma","arthritis"],"High glucose suggests diabetes.")
H('482.d.8.D',3,"Epidemiologists collect data on how many people get a disease and where. This type of data helps identify:","trends",["colors","songs","names"],"Epidemiological data show trends.")
H('482.d.8.D',4,"A graph showing flu cases climbing each week for a month suggests a growing:","outbreak",["recovery","vaccine","budget"],"Rising cases show an outbreak.")
H('482.d.8.E',3,"Diseases such as HIV and tuberculosis threaten world health, and a good plan to reduce them would include education, access to treatment, and:","prevention",["denial","delay","neglect"],"Prevention is key.")
H('482.d.8.E',4,"To address a disease that threatens world health, groups such as the World Health Organization help countries with surveillance, vaccination, and:","health education",["tourism ads","fashion shows","sports leagues"],"Global solutions include education.")
H('482.d.8.F',3,"A prevention plan for heart disease might include eating a healthy diet, not smoking, and getting regular:","exercise",["bed rest only","fast food","sugary drinks"],"Behavior affects risk.")
H('482.d.8.F',4,"A plan to reduce lung cancer risk focuses on a behavior that contributes strongly to the disease:","avoiding tobacco",["watching television","eating fruit","drinking water"],"Tobacco is a major cause.")
# ---- 483 Pharmacy Technician ----
H('483.d.1.A',3,"A pharmacy technician greets every customer politely and listens without judging. This shows a respectful and professional:","attitude",["schedule","uniform","budget"],"Professionalism builds trust.")
H('483.d.1.A',4,"A customer is upset about waiting for a refill. The best technician response is to stay calm, apologize for the delay, and:","offer to help",["argue back","ignore the customer","walk away"],"De-escalate and help.")
H('483.d.1.B',3,"When speaking with an older adult who has difficulty hearing, a technician should face the person, speak clearly, and:","avoid shouting",["shout","mumble","turn away"],"Adapt communication to the person.")
H('483.d.1.B',4,"To communicate with a patient who speaks little English, a pharmacy can use an interpreter service and simple, clear:","written instructions",["slang","jargon","abbreviations"],"Clear instructions help.")
H('483.d.2.A',3,"In a pharmacy, the abbreviation tab on a prescription means:","tablet",["table","tablespoon","tube"],"tab = tablet.")
H('483.d.2.A',4,"The abbreviation gtt on a prescription means:","drop",["gram","gallon","grain"],"gtt = drops.")
H('483.d.2.B',3,"A pharmacy that fills prescriptions for the general public, such as a drugstore, is a community pharmacy, while one inside a hospital is an:","institutional pharmacy",["online pharmacy","retail pharmacy","vet pharmacy"],"Hospital pharmacies are institutional.")
H('483.d.2.B',4,"In an institutional pharmacy, medication is often ordered with a medication order, while in a community pharmacy a patient brings a:","prescription",["receipt","coupon","badge"],"Terms differ by setting.")
H('483.d.2.C',3,"The sig code q.d. on a prescription means to take the medicine:","once a day",["twice a day","every hour","at night only"],"q.d. = daily.")
H('483.d.2.C',4,"The sig code b.i.d. on a prescription means to take the medicine:","twice a day",["once a day","four times a day","every other day"],"b.i.d. = twice daily.")
H('483.d.3.A',3,"Medications that can harm workers, such as chemotherapy drugs, must be handled and thrown away as:","hazardous waste",["ordinary trash","recycling","compost"],"Hazardous drugs need special disposal.")
H('483.d.3.A',4,"Unused non-hazardous medications cannot just be thrown in the regular trash in a pharmacy. They are usually sent through a reverse distributor or approved:","disposal program",["gift program","sale","drain"],"Proper disposal prevents harm.")
H('483.d.3.B',3,"A prescription for a Schedule II drug generally cannot be refilled and must include the prescriber's signature and the patient's:","name and address",["favorite color","pet's name","bank balance"],"Controlled substance rules are strict.")
H('483.d.3.B',4,"The federal agency that regulates controlled substances is the Drug Enforcement:","Administration",["Association","Alliance","Authority"],"The DEA.")
H('483.d.3.C',3,"When the FDA finds that a medicine may be harmful, it can ask for a:","recall",["sale","discount","promotion"],"Recalls remove unsafe products.")
H('483.d.3.C',4,"A Class I recall is the most serious type and is used when a product could cause serious harm or:","death",["delay","confusion","boredom"],"Class I risks serious harm.")
H('483.d.3.D',3,"Statutes passed by state and federal governments affect how a pharmacy dispenses medication. A technician must be able to interpret and apply these:","laws",["rumors","fashions","trends"],"Laws guide practice.")
H('483.d.3.D',4,"A pharmacy follows the Health Insurance Portability and Accountability Act to protect patients':","privacy",["parking","pricing","paperwork"],"HIPAA protects health information.")
H('483.d.3.E',3,"State and federal regulations about pharmacy practice tell technicians what tasks they may perform under the supervision of a:","pharmacist",["manager","clerk","cashier"],"Technicians work under a pharmacist.")
H('483.d.3.E',4,"Rules limit how many pharmacy technicians a pharmacist may supervise at one time, called the pharmacist-to-technician:","ratio",["salary","discount","schedule"],"Ratios are set by law.")
H('483.d.3.F',3,"A pharmacy follows professional standards and legal rules, which is called:","compliance",["defiance","negligence","avoidance"],"Compliance means following rules.")
H('483.d.3.F',4,"Keeping accurate records, checking IDs for controlled substances, and storing drugs securely are all part of pharmacy:","compliance",["advertising","decoration","entertainment"],"Compliance protects patients.")
H('483.d.4.A',3,"Tylenol is a brand name, and its generic name is:","acetaminophen",["ibuprofen","aspirin","naproxen"],"Tylenol is acetaminophen.")
H('483.d.4.A',4,"A medicine's classification, such as antihypertensive, tells what group it belongs to, while its indication tells what it is used to:","treat",["cost","sell","store"],"Indication means use.")
H('483.d.4.B',3,"A condition in which a drug should not be used because it could cause harm to a patient is a:","contraindication",["indication","prescription","refill"],"Contraindications mean do not use.")
H('483.d.4.B',4,"When two medicines taken together change each other's effects, the problem is called a drug:","interaction",["recall","dose","label"],"Interactions can be dangerous.")
H('483.d.4.C',3,"Medicines such as warfarin and digoxin have a narrow therapeutic index, which means the safe dose range is:","small",["large","endless","unimportant"],"NTI drugs need care.")
H('483.d.4.C',4,"Because the difference between a helpful and a harmful dose is tiny for an NTI drug, patients on these medications need careful:","monitoring",["advertising","discounts","parking"],"NTI drugs are monitored.")
H('483.d.4.D',3,"A technician who needs standards for compounding sterile preparations would look in a reference such as the United States:","Pharmacopeia",["Postal Guide","Telephone Book","Almanac"],"USP provides standards.")
H('483.d.4.D',4,"The reference book that lists FDA-approved drugs with therapeutic equivalence ratings is nicknamed the:","Orange Book",["Blue Book","Red Book","Green Book"],"The Orange Book lists equivalents.")
H('483.d.5.A',3,"A complete prescription includes the patient's name, the drug name, the strength, the directions, and the prescriber's:","signature",["hobby","hat size","phone model"],"Completeness is checked.")
H('483.d.5.A',4,"A prescription that does not list the drug strength is incomplete, so the technician should ask the pharmacist to contact the:","prescriber",["patient's neighbor","insurance clerk","delivery driver"],"Clarify with the prescriber.")
H('483.d.5.B',3,"To enter a new customer's prescription, the technician collects the patient's name, date of birth, address, and:","insurance information",["favorite food","pet's name","shoe size"],"Demographics and insurance are needed.")
H('483.d.5.B',4,"The technician should also ask a new patient about allergies, because this information can help the pharmacist avoid a harmful:","reaction",["delay","discount","refill"],"Allergy info protects safety.")
H('483.d.5.C',3,"When assisting the pharmacist in collecting a patient's medication history, a technician records the medicines the patient takes and any:","allergies",["birthdays","hobbies","vacations"],"Allergies are key.")
H('483.d.5.C',4,"Recording over-the-counter drugs and supplements in the patient profile helps the pharmacist screen for:","interactions",["coupons","holidays","hobbies"],"OTC drugs can interact.")
H('483.d.5.D',3,"A prescription says take 1 tablet three times a day for 10 days. The total number of tablets to dispense is:","30",["3","13","10"],"1 x 3 x 10 = 30.")
H('483.d.5.D',4,"A prescription for a liquid says take 5 mL twice a day for 7 days. The total volume to dispense is:","70 mL",["35 mL","14 mL","12 mL"],"5 x 2 x 7 = 70.")
H('483.d.5.E',3,"Items such as glucose meters, test strips, and lancets are examples of:","diabetic supplies",["cleaning products","office supplies","toys"],"Diabetic supplies are sold in pharmacies.")
H('483.d.5.E',4,"A spacer is a device that attaches to an inhaler so that the patient gets more of the medication into the:","lungs",["stomach","skin","eyes"],"Spacers improve delivery.")
H('483.d.5.F',3,"A lot number on a medicine package helps the pharmacy find which products are affected during a:","recall",["sale","survey","parade"],"Lot numbers trace products.")
H('483.d.5.F',4,"The expiration date on a medication tells the pharmacy when the drug should no longer be:","used or dispensed",["labeled","stored in a refrigerator","counted"],"Expired drugs are removed.")
H('483.d.5.G',3,"A technician practices infection control by washing hands before preparing medicines and wearing:","gloves",["jewelry","a hat only","sandals"],"Gloves and hand hygiene.")
H('483.d.5.G',4,"Never reusing a counting tray for different drugs without cleaning it helps prevent cross-contamination and:","errors",["savings","growth","speed"],"Clean trays prevent mix-ups.")
H('483.d.5.H',3,"A pharmacy follows cleaning standards, such as washing hands for at least 20 seconds and keeping counters:","disinfected",["decorated","cluttered","dusty"],"Clean areas protect patients.")
H('483.d.5.H',4,"Before compounding a sterile product, the technician cleans the hood with an approved disinfectant such as sterile 70 percent:","isopropyl alcohol",["vinegar","soap bubbles","water"],"Alcohol disinfects surfaces.")
H('483.d.5.I',3,"A state board of pharmacy licenses pharmacies and pharmacists and also regulates pharmacy:","technicians",["customers","vendors","tourists"],"Boards regulate practice.")
H('483.d.5.I',4,"A state board of pharmacy can discipline a pharmacist who breaks pharmacy laws, for example by suspending a:","license",["lunch","parking pass","uniform"],"Boards enforce laws.")
H('483.d.6.A',3,"Medications that can cause serious harm if used wrongly are called high-alert medications, and drugs with names that resemble each other are called:","look-alike/sound-alike drugs",["fast-acting drugs","expired drugs","generic drugs only"],"LASA drugs cause mix-ups.")
H('483.d.6.A',4,"Hydroxyzine and hydralazine are examples of drugs whose names look and sound similar, which creates a risk of a dispensing:","error",["reward","discount","benefit"],"Similar names cause errors.")
H('483.d.6.B',3,"Writing part of a drug name in capital letters, such as predniSONE and predniSOLONE, is called:","Tall Man lettering",["Big Name printing","Bold naming","Title casing"],"Tall Man letters highlight differences.")
H('483.d.6.B',4,"A strategy to prevent errors is to check the drug name, strength, and patient name against the prescription, using at least two:","patient identifiers",["colors","coins","pens"],"Two identifiers prevent errors.")
H('483.d.6.C',3,"A prescription for an amount of medicine much higher than usual is an example of an abnormal:","dose",["name","pen","label"],"Abnormal doses are flagged.")
H('483.d.6.C',4,"A refill requested too soon after the last fill, called an early refill, could be a sign of misuse or an:","error",["birthday","discount","sale"],"Early refills prompt review.")
H('483.d.6.D',3,"A pharmacist has a professional duty to check prescriptions for safety before dispensing. This process is called drug utilization:","review",["decoration","marketing","pricing"],"DUR checks safety.")
H('483.d.6.D',4,"The pharmacist is responsible for counseling the patient on how to take the medicine and its possible:","side effects",["costs of parking","store hours","colors"],"Counseling is the pharmacist's role.")
H('483.d.6.E',3,"A technician notices that a patient's new prescription is for a drug the patient is already taking. The technician should tell the pharmacist about the possible:","duplication",["discount","sale","birthday"],"Duplicate therapy is flagged.")
H('483.d.6.E',4,"Noticing a patient who has two different brand names of the same drug in the profile can help the pharmacist prevent an:","overdose",["increase in sales","refund","new order"],"Duplicate ingredients are dangerous.")
H('483.d.6.F',3,"A pharmacy technician helps keep patients safe by following procedures, double-checking work, and reporting:","mistakes",["gossip","rumors","jokes"],"Report errors.")
H('483.d.6.F',4,"A culture of safety encourages reporting a near miss, which is an error that was caught before it reached the:","patient",["manager","shelf","supplier"],"Near misses teach lessons.")
H('483.d.6.G',3,"When a medication error is discovered after a drug has reached a patient, the technician should tell the pharmacist:","immediately",["next week","never","after lunch"],"Prompt reporting protects patients.")
H('483.d.6.G',4,"After an error, the pharmacy completes an incident report to find out what happened and how to prevent it from happening:","again",["quietly","privately","slowly"],"Reports prevent recurrence.")
H('483.d.6.H',3,"Basic safety in a pharmacy includes knowing where the fire extinguisher, eyewash station, and emergency:","exits are",["menus are","coupons are","seats are"],"Emergency preparedness.")
H('483.d.6.H',4,"In an emergency such as a fire or a power outage, the technician follows the pharmacy's emergency:","plan",["advertisement","menu","joke"],"Plans protect people.")
H('483.d.7.A',3,"Some medications must be kept in a refrigerator at 36 to 46 degrees Fahrenheit, which is an example of proper storage in regard to:","temperature",["color","size","price"],"Temperature controls stability.")
H('483.d.7.A',4,"Medicines that are sensitive to light, such as nitroglycerin, are stored in dark amber or opaque containers because light can:","break them down",["make them cheaper","make them stronger","change their label"],"Light degrades drugs.")
H('483.d.7.B',3,"A list of medications that a hospital or insurance plan has approved for use is a:","formulary",["catalog","invoice","recall"],"A formulary lists preferred drugs.")
H('483.d.7.B',4,"The purpose of a formulary is to promote safe, effective, and cost-effective choices of:","medications",["furniture","uniforms","computers"],"Formularies guide prescribing.")
H('483.d.7.C',3,"Taking expired drugs off the shelves and checking dates regularly are procedures of inventory:","control",["growth","decor","trade"],"Inventory control prevents expired stock.")
H('483.d.7.C',4,"A pharmacy that uses a perpetual inventory system keeps a continuous count of its:","stock",["employees","customers","windows"],"Perpetual inventory tracks stock.")
H('483.d.7.D',3,"When the pharmacy needs more of a drug, the technician places an order with a drug wholesaler, which is the process of:","purchasing",["selling","returning","expiring"],"Purchasing restocks inventory.")
H('483.d.7.D',4,"A purchase order for a controlled substance in Schedule II requires a special form called DEA Form:","222",["22","444","1"],"DEA 222 form.")
H('483.d.7.E',3,"Expired medications that have been removed from stock are typically separated and returned to a company called a reverse:","distributor",["customer","doctor","owner"],"Expired drugs go to reverse distributors.")
H('483.d.7.E',4,"Expired medications must be clearly marked and stored apart from active stock so they are not accidentally:","dispensed",["counted","cleaned","praised"],"Separate expired drugs.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_71.jsonl"))
